import React, { useEffect, useState } from 'react';
import Login from './components/Login';
import Register from './components/Register';
import ProductList from './components/ProductList';
import Cart from './components/Cart';
import { fetchProducts } from './api';

export default function App() {
  const [page, setPage] = useState('products'); // pages: login, register, products, cart
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);
  const [loggedIn, setLoggedIn] = useState(!!localStorage.getItem('token'));

  useEffect(() => {
    fetchProducts()
      .then(setProducts)
      .catch(err => console.error('fetchProducts ERROR:', err));
  }, []);

  /** Add product to cart */
  function addToCart(product) {
    setCart(prev => {
      const found = prev.find(item => item.productId === product.id);
      if (found) {
        return prev.map(item =>
          item.productId === product.id
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [...prev, { productId: product.id, name: product.name, price: product.price, quantity: 1 }];
    });
  }

  /** Remove from cart */
  function removeFromCart(productId) {
    setCart(prev => prev.filter(item => item.productId !== productId));
  }

  function clearCart() {
    setCart([]);
  }

  /** Logout */
  function logout() {
    localStorage.removeItem('token');
    setLoggedIn(false);
    setPage('products');
  }

  return (
    <div className="container">

      {/* ---------------- HEADER ---------------- */}
      <header className="header">
        <h1 className="title">E-Commerce</h1>

        <nav className="navbar">
          <button onClick={() => setPage("products")}>Products</button>

          {!loggedIn && (
            <>
              <button onClick={() => setPage("login")}>Login</button>
              <button onClick={() => setPage("register")}>Register</button>
            </>
          )}

          <button onClick={() => setPage("cart")}>
            Cart ({cart.reduce((sum, item) => sum + item.quantity, 0)})
          </button>

          {loggedIn && (
            <button className="logoutBtn" onClick={logout}>Logout</button>
          )}
        </nav>
      </header>

      {/* ---------------- MAIN CONTENT ---------------- */}
      <main className="content">
        {page === 'login' && (
          <Login onLogin={() => { setLoggedIn(true); setPage('products'); }} />
        )}

        {page === 'register' && (
          <Register onRegister={() => setPage('login')} />
        )}

        {page === 'products' && (
          <ProductList products={products} onAdd={addToCart} />
        )}

        {page === 'cart' && (
          <Cart cart={cart} setCart={setCart} onOrderPlaced={clearCart} />
        )}
      </main>
    </div>
  );
}
